"""Import an HTML presentation (for example generated by an LLM) as a Proposal.

The HTML is parsed statically: scripts are never executed and external resources are never fetched.
Slides are split by structure, content is extracted, then mapped to our slide types using explicit
`data-type` hints first and title keywords second. Anything unclear becomes a bullets slide.
"""
from __future__ import annotations

import re
from dataclasses import dataclass, field

import lxml.html
from lxml import etree

from .models import (Activity, Assumptions, Cost, CostLine, Flow, FlowEdge, FlowNode, Gantt, Meta, NextStep, NextSteps,
                     Proposal, Risk, Risks, ScopeSpec, Slide)

SKIP = {"script", "style", "noscript", "iframe", "template", "head", "meta", "link", "nav", "button"}
HEADINGS = {"h1", "h2", "h3", "h4", "h5", "h6"}
TEXT_BLOCKS = {"p", "blockquote", "pre", "figcaption", "dt", "dd", "summary"}
TYPES = {"title", "bullets", "assumptions", "scope", "risks", "next_steps", "gantt", "cost", "flow"}


def _cls(el, token: str) -> bool:
    return f" {token} " in f" {(el.get('class') or '').lower().replace('-', ' ')} ".replace("  ", " ") or \
        token in (el.get("class") or "").lower().split()


def _txt(el) -> str:
    return re.sub(r"\s+", " ", "".join(el.itertext())).strip()


@dataclass
class Raw:
    title: str = ""
    hint: str = ""
    blocks: list[tuple] = field(default_factory=list)  # ("h", level, text) ("p", text) ("li", text, depth) ("table", rows) ("img",) ("svg",)
    notes: str = ""

    def texts(self) -> list[str]:
        return [b[1] if b[0] == "p" else b[2] if b[0] == "h" else b[1] for b in self.blocks if b[0] in ("p", "h", "li")]


# --------------------------------------------------------------- slide split
def _is_slide_class(el) -> bool:
    return el.get("data-slide") is not None or "slide" in (el.get("class") or "").lower().split()


def _outermost(nodes):
    keep = []
    s = set(nodes)
    for n in nodes:
        if not any(a in s for a in n.iterancestors()):
            keep.append(n)
    return keep


def find_slides(root) -> tuple[list, str]:
    nodes = [e for e in root.iter() if isinstance(e.tag, str) and _is_slide_class(e)]
    if nodes:
        return _outermost(nodes), "slide markers"
    sections = [e for e in root.iter("section")]
    if sections:
        out = []
        for s in _outermost(sections):
            inner = s.xpath(".//section")
            out.extend(_outermost(inner) if inner else [s])
        return out, "sections"
    arts = _outermost([e for e in root.iter("article")])
    if len(arts) > 1:
        return arts, "articles"
    return [], "headings"


def split_by_headings(body) -> list[etree._Element]:
    """Fallback: wrap the content between h1/h2 headings into synthetic slide elements."""
    groups, cur = [], None
    for ch in body:
        if not isinstance(ch.tag, str) or ch.tag in SKIP:
            continue
        if ch.tag in ("h1", "h2") or ch.tag == "hr":
            if ch.tag == "hr":
                cur = None
                continue
            cur = lxml.html.Element("div")
            groups.append(cur)
        if cur is not None:
            cur.append(ch)
    return groups


# ------------------------------------------------------------- extraction
def _own_text(li) -> str:
    parts = [li.text or ""]
    for ch in li:
        if ch.tag in ("ul", "ol"):
            parts.append(ch.tail or "")
            continue
        parts.append(_txt(ch))
        parts.append(ch.tail or "")
    return re.sub(r"\s+", " ", " ".join(parts)).strip()


def _table_rows(t) -> list[list[tuple[str, str]]]:
    """Rows of (text, style-flag) cells; the flag marks highlighted cells (used for Gantt bars)."""
    rows = []
    for tr in t.iter("tr"):
        cells = []
        for c in tr:
            if c.tag not in ("td", "th"):
                continue
            style = (c.get("style") or "").lower()
            klass = (c.get("class") or "").lower()
            on = bool(re.search(r"background(-color)?\s*:\s*(?!\s*(#fff\b|#ffffff|white|transparent|none|inherit))", style)) \
                or bool(re.search(r"\b(on|active|bar|filled|busy|fill|done|gantt-bar)\b", klass)) or c.get("data-active") is not None
            cells.append((_txt(c), "on" if on else ""))
        if cells:
            rows.append(cells)
    return rows


def extract(el) -> Raw:
    raw = Raw(hint=(el.get("data-type") or "").strip().lower().replace("-", "_"))
    notes: list[str] = []

    def is_notes(e) -> bool:
        return e.tag == "aside" or _cls(e, "notes") or _cls(e, "speaker notes") or e.get("data-notes") is not None

    def visit(e, depth: int) -> None:
        if not isinstance(e.tag, str):
            return
        tag = e.tag.lower()
        if tag in SKIP:
            return
        if is_notes(e):
            notes.append(e.get("data-notes") or _txt(e))
            return
        if tag in HEADINGS:
            t = _txt(e)
            if t:
                raw.blocks.append(("h", int(tag[1]), t))
        elif tag in ("ul", "ol"):
            for li in e:
                if li.tag == "li":
                    t = _own_text(li)
                    if t:
                        raw.blocks.append(("li", t, depth))
                    for sub in li:
                        if sub.tag in ("ul", "ol"):
                            visit(sub, depth + 1)
        elif tag == "table":
            rows = _table_rows(e)
            if rows:
                raw.blocks.append(("table", rows))
        elif tag in TEXT_BLOCKS:
            t = _txt(e)
            if t:
                raw.blocks.append(("p", t))
        elif tag == "img":
            raw.blocks.append(("img", e.get("alt") or ""))
        elif tag == "svg":
            raw.blocks.append(("svg", _txt(e)))
        else:
            if (e.text or "").strip():
                raw.blocks.append(("p", re.sub(r"\s+", " ", e.text).strip()))
            for ch in e:
                visit(ch, depth)
                if (ch.tail or "").strip():
                    raw.blocks.append(("p", re.sub(r"\s+", " ", ch.tail).strip()))

    for ch in el:
        visit(ch, 0)
        if (ch.tail or "").strip():
            raw.blocks.append(("p", re.sub(r"\s+", " ", ch.tail).strip()))
    if (el.text or "").strip():
        raw.blocks.insert(0, ("p", re.sub(r"\s+", " ", el.text).strip()))
    raw.notes = "\n".join(n for n in notes if n).strip()

    attr = el.get("data-title")
    if attr:
        raw.title = attr.strip()
    else:
        first = next((b for b in raw.blocks if b[0] == "h"), None)
        if first is not None:
            raw.title = first[2]
            raw.blocks.remove(first)
    return raw


# ---------------------------------------------------------------- mapping
_IMPACT = {"high": "High", "critical": "High", "severe": "High", "h": "High", "medium": "Medium", "med": "Medium",
           "moderate": "Medium", "m": "Medium", "low": "Low", "minor": "Low", "l": "Low"}


def _col(header: list[str], *words: str) -> int | None:
    for i, h in enumerate(header):
        if any(w in h.lower() for w in words):
            return i
    return None


def _tables(raw: Raw):
    return [b[1] for b in raw.blocks if b[0] == "table"]


def _items(raw: Raw) -> list[str]:
    li = [b[1] for b in raw.blocks if b[0] == "li"]
    return li or [b[1] for b in raw.blocks if b[0] == "p"]


def _num(t: str) -> float | None:
    s = t.replace(",", "").replace("$", "").replace("€", "").replace("£", "").strip()
    m = re.fullmatch(r"(-?\d+(?:\.\d+)?)\s*([kKmM])?", s)
    if not m:
        return None
    v = float(m.group(1))
    return v * {"k": 1e3, "m": 1e6}.get((m.group(2) or "").lower(), 1)


def _as_risks(raw: Raw, w: list[str]):
    tabs = _tables(raw)
    if tabs and len(tabs[0]) > 1:
        head = [c[0] for c in tabs[0][0]]
        ri = _col(head, "risk", "dependency", "issue") or 0
        ii = _col(head, "impact", "severity", "rating")
        mi = _col(head, "mitigation", "response", "action", "plan")
        items = []
        for row in tabs[0][1:]:
            cells = [c[0] for c in row]
            imp = _IMPACT.get(cells[ii].strip().lower(), "Medium") if ii is not None and ii < len(cells) else "Medium"
            mit = cells[mi] if mi is not None and mi < len(cells) else ""
            if cells and cells[ri]:
                items.append(Risk(risk=cells[ri], impact=imp, mitigation=mit))
        if items:
            return Slide(type="risks", risks=Risks(title=raw.title or "Risks and dependencies", items=items))
    items = _items(raw)
    if items:
        w.append("risks were a list, so impact defaults to Medium; set impact and mitigation in the editor")
        return Slide(type="risks", risks=Risks(title=raw.title or "Risks and dependencies", items=[Risk(risk=t) for t in items]))
    return None


def _as_next_steps(raw: Raw, w: list[str]):
    tabs = _tables(raw)
    if tabs and len(tabs[0]) > 1:
        head = [c[0] for c in tabs[0][0]]
        ai = _col(head, "action", "step", "task", "what") or 0
        oi = _col(head, "owner", "who", "responsible")
        di = _col(head, "due", "when", "date", "timeline")
        items = []
        for row in tabs[0][1:]:
            cells = [c[0] for c in row]
            if cells and cells[ai]:
                items.append(NextStep(action=cells[ai], owner=cells[oi] if oi is not None and oi < len(cells) else "",
                                      due=cells[di] if di is not None and di < len(cells) else ""))
        if items:
            return Slide(type="next_steps", next_steps=NextSteps(title=raw.title or "Next steps", items=items))
    items = _items(raw)
    if items:
        return Slide(type="next_steps", next_steps=NextSteps(title=raw.title or "Next steps", items=[NextStep(action=t) for t in items]))
    return None


def _as_scope(raw: Raw, w: list[str]):
    side, ins, outs = "in", [], []
    for b in raw.blocks:
        if b[0] == "h" or (b[0] == "p" and len(b[1]) < 40):
            t = b[2] if b[0] == "h" else b[1]
            if re.search(r"out[- ]of[- ]scope|not (in )?scope|excluded|exclusions", t, re.I):
                side = "out"
            elif re.search(r"in[- ]scope|included|inclusions", t, re.I):
                side = "in"
        elif b[0] == "li":
            (ins if side == "in" else outs).append(b[1])
    if not ins and not outs:
        return None
    if ins and not outs:
        w.append("no out-of-scope items were found; add exclusions explicitly")
    return Slide(type="scope", scope=ScopeSpec(title=raw.title or "Scope", in_scope=ins, out_scope=outs))


def _as_assumptions(raw: Raw, w: list[str]):
    items = _items(raw)
    return Slide(type="assumptions", assumptions=Assumptions(title=raw.title or "Assumptions", items=items, numbered=True)) if items else None


def _as_gantt(raw: Raw, w: list[str]):
    tabs = _tables(raw)
    if not tabs or len(tabs[0]) < 2:
        return None
    rows = tabs[0]
    head = [c[0] for c in rows[0]]
    week_cols = [i for i, h in enumerate(head) if i > 0 and re.search(r"\b(w(eek)?\s*\d+|\d+)\b", h.lower())]
    if len(week_cols) < 2:
        return None
    acts, warned = [], False
    for row in rows[1:]:
        if len(row) <= week_cols[0]:
            continue
        name = row[0][0]
        active = [k + 1 for k, ci in enumerate(week_cols) if ci < len(row) and (row[ci][1] == "on" or (row[ci][0] and not re.fullmatch(r"w?\d+", row[ci][0].lower())))]
        if name and active:
            if active != list(range(active[0], active[-1] + 1)) and not warned:
                w.append("some activities have gaps between active weeks; shown as one continuous bar")
                warned = True
            acts.append(Activity(name=name, start_week=active[0], end_week=active[-1]))
    if not acts:
        return None
    import datetime
    return Slide(type="gantt", gantt=Gantt(title=raw.title or "Execution plan", start_date=datetime.date.today(), activities=acts))


def _as_cost(raw: Raw, w: list[str]):
    tabs = _tables(raw)
    if not tabs or len(tabs[0]) < 2:
        return None
    rows = tabs[0]
    head = [c[0] for c in rows[0]]
    year_cols = [i for i, h in enumerate(head) if i > 0 and not re.fullmatch(r"total", h.strip().lower())]
    if not year_cols:
        return None
    lines, benefits = [], []
    for row in rows[1:]:
        label = row[0][0]
        vals = [(_num(row[i][0]) if i < len(row) else None) for i in year_cols]
        if not label or label.lower().startswith("total") or all(v is None for v in vals):
            continue
        nums = [v or 0.0 for v in vals]
        if "benefit" in label.lower() or "saving" in label.lower():
            benefits = nums
        else:
            lines.append(CostLine(head=label, values=nums))
    if not lines:
        return None
    years = [head[i] for i in year_cols]
    cur = "$"
    m = re.search(r"([$€£])", " ".join(c[0] for r in rows for c in r))
    if m:
        cur = m.group(1)
    w.append("cost one-time/recurring kinds default to mixed; set them in the editor")
    return Slide(type="cost", cost=Cost(title=raw.title or "Cost", currency=cur, years=years, lines=lines,
                                        benefits=benefits if len(benefits) == len(years) else []))


def _as_flow(raw: Raw, w: list[str]):
    items = _items(raw)
    if len(items) < 2:
        return None
    w.append("converted a list into a simple linear flow; refine kinds and branches in the editor")
    nodes = [FlowNode(id="start", label="Start", kind="start")]
    nodes += [FlowNode(id=f"n{i}", label=t[:80], kind="process") for i, t in enumerate(items, 1)]
    nodes.append(FlowNode(id="end", label="End", kind="end"))
    edges = [FlowEdge(src=a.id, dst=b.id) for a, b in zip(nodes, nodes[1:])]
    return Slide(type="flow", flow=Flow(title=raw.title or "Process flow", nodes=nodes, edges=edges))


def _kind_from_title(title: str) -> str:
    t = title.lower()
    rules = [("assumption", "assumptions"), ("risk", "risks"), ("depend", "risks"), ("next step", "next_steps"),
             ("action item", "next_steps"), ("scope", "scope"), ("timeline", "gantt"), ("execution plan", "gantt"),
             ("roadmap", "gantt"), ("cost", "cost"), ("budget", "cost"), ("cba", "cost"), ("investment", "cost")]
    return next((k for key, k in rules if key in t), "")


def map_slide(raw: Raw, number: int, warnings: list[str]) -> Slide:
    w: list[str] = []
    kind = raw.hint if raw.hint in TYPES else _kind_from_title(raw.title)
    mapper = {"assumptions": _as_assumptions, "risks": _as_risks, "next_steps": _as_next_steps, "scope": _as_scope,
              "gantt": _as_gantt, "cost": _as_cost, "flow": _as_flow}.get(kind)
    slide = mapper(raw, w) if mapper else None
    if kind and mapper and slide is None:
        w.append(f"looked like a {kind.replace('_', ' ')} slide but its content did not match; imported as bullets")
    if slide is None:
        bullets: list[str] = []
        for b in raw.blocks:
            if b[0] == "li":
                bullets.append(("  " * b[2]) + b[1] if b[2] else b[1])
            elif b[0] == "p":
                bullets.append(b[1])
            elif b[0] == "h":
                bullets.append(b[2])
            elif b[0] == "table":
                bullets += [" | ".join(dict.fromkeys(c[0] for c in row if c[0])) for row in b[1] if any(c[0] for c in row)]
        slide = Slide(type="bullets", title=raw.title or f"Slide {number}", bullets=[x.strip() for x in bullets if x.strip()][:25])
    pics = sum(1 for b in raw.blocks if b[0] == "img")
    svgs = sum(1 for b in raw.blocks if b[0] == "svg")
    if pics:
        w.append(f"{pics} image(s) were not imported")
    if svgs:
        w.append(f"{svgs} SVG graphic(s) were not imported; recreate diagrams as a flow")
    slide.notes = raw.notes
    warnings += [f"Slide {number} ({raw.title or 'untitled'}): {m}." for m in w]
    return slide


# ------------------------------------------------------------------- entry
def from_html(data: bytes) -> tuple[Proposal, list[str], str]:
    text = data.decode("utf-8", errors="replace")
    try:
        root = lxml.html.fromstring(text)
    except (etree.ParserError, etree.XMLSyntaxError, ValueError) as e:
        raise ValueError("could not parse the HTML file") from e
    for bad in root.xpath("//script|//style|//noscript|//iframe|//template"):
        bad.getparent().remove(bad) if bad.getparent() is not None else None
    for c in root.xpath("//comment()"):
        if c.getparent() is not None:
            c.getparent().remove(c)
    page_title = _txt(root.find(".//title")) if root.find(".//title") is not None else ""
    body = root.find(".//body") if root.find(".//body") is not None else root
    nodes, how = find_slides(body)
    if not nodes:
        nodes = split_by_headings(body)
    if not nodes:
        raise ValueError("no slides found: expected <section>, class=\"slide\", data-slide, or h1/h2 headings")
    warnings: list[str] = [f"Split into {len(nodes)} slide(s) using {how}."] if how != "slide markers" else []
    raws = [extract(n) for n in nodes]
    raws = [r for r in raws if r.title or r.blocks]
    if not raws:
        raise ValueError("the slides had no text content")
    first = raws[0]
    meta = Meta(title=(first.title or page_title or "Imported deck")[:200], subtitle="")
    slides: list[Slide] = []
    for i, r in enumerate(raws, start=1):
        if i == 1 and (r.hint == "title" or (len(r.blocks) <= 3 and not r.hint and not _kind_from_title(r.title)
                                             and not any(b[0] in ("table", "li") for b in r.blocks))):
            texts = r.texts()
            meta.subtitle = (texts[0] if texts else "")[:200]
            slides.append(Slide(type="title", notes=r.notes))
        else:
            slides.append(map_slide(r, i, warnings))
    if slides[0].type != "title":
        slides.insert(0, Slide(type="title"))
        warnings.append("Added a title slide from the page title.")
    return Proposal(meta=meta, slides=slides), warnings, "html"
